import React, { useEffect } from "react";

/* ─────────────────────────────────────────────────────────────
   Bank / payment-channel logos for ROS India.
   Small embedded icons (no network request) + helpers:
     <BankIcon pay="HDFC" size={18}/>           just the logo
     <BankBadge pay="HDFC"/>                    tinted pill: logo + short name
                                                (name hidden on phones → logo only)
     <BankPicker value options onChange/>       tap-a-logo selector for forms
     <BankMenu value options onPick onClose/>   small popup menu for the Sales list
   Unknown values fall back to plain text, so nothing can break.
   ───────────────────────────────────────────────────────────── */

const LOGO = {
  SIB:     "data:image/png;base64,",
  HDFC:    "data:image/png;base64,",
  FEDERAL: "data:image/png;base64,",
  PAYPAL:  "data:image/png;base64,",
};

/* simple vector icons for the two non-bank channels */
const ShopSvg = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke="#059669" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M5 8h14l-1 12H6L5 8z" /><path d="M9 8V6a3 3 0 0 1 6 0v2" />
  </svg>
);
const CashSvg = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke="#15803d" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <rect x="2.5" y="6" width="19" height="12" rx="2" /><circle cx="12" cy="12" r="2.6" /><path d="M6 9.5v.01M18 14.5v.01" />
  </svg>
);

export const BANK_META = {
  "SIB":          { short: "SIB",     name: "South Indian Bank", color: "#b91c1c", bg: "#fef2f2", border: "#fecaca", logo: LOGO.SIB },
  "HDFC":         { short: "HDFC",    name: "HDFC Bank",         color: "#1d4ed8", bg: "#eff6ff", border: "#bfdbfe", logo: LOGO.HDFC },
  "FEDERAL BANK": { short: "Federal", name: "Federal Bank",      color: "#c2410c", bg: "#fff7ed", border: "#fed7aa", logo: LOGO.FEDERAL },
  "PAYPAL INDIA": { short: "PayPal",  name: "PayPal India",      color: "#4338ca", bg: "#eef2ff", border: "#c7d2fe", logo: LOGO.PAYPAL },
  "SHOP":         { short: "Shop",    name: "Shop",              color: "#059669", bg: "#ecfdf5", border: "#a7f3d0", svg: ShopSvg },
  "CASH":         { short: "Cash",    name: "Cash",              color: "#15803d", bg: "#f0fdf4", border: "#bbf7d0", svg: CashSvg },
};

/* any stored value → one of the keys above (or null if we don't know it) */
export const bankKey = (pay) => {
  const p = String(pay == null ? "" : pay).trim().toUpperCase();
  if (!p) return "SHOP";
  if (p === "BANK" || p === "SIB") return "SIB";
  if (p === "HDFC") return "HDFC";
  if (p === "FEDERAL BANK" || p === "FEDERAL") return "FEDERAL BANK";
  if (p === "PAYPAL INDIA" || p === "PAYPAL") return "PAYPAL INDIA";
  if (p === "SHOP" || p === "SHOPIFY") return "SHOP";
  if (p === "CASH") return "CASH";
  return null;
};

/* phones: hide the short name, keep the logo (picker tiles keep their name) */
let _stylesIn = false;
const ensureStyles = () => {
  if (_stylesIn || typeof document === "undefined") return;
  _stylesIn = true;
  const st = document.createElement("style");
  st.setAttribute("data-bank-logos", "1");
  st.textContent = "@media (max-width:767px){.bk-name{display:none !important}.bk-pill{padding:3px 6px !important}.bk-tile .bk-name{display:inline !important}}";
  document.head.appendChild(st);
};

export const BankIcon = ({ pay, size = 18 }) => {
  ensureStyles();
  const k = bankKey(pay); const m = k && BANK_META[k];
  if (!m) return null;
  if (m.logo) return (
    <img src={m.logo} alt={m.name} title={m.name} draggable={false}
      style={{ width: "auto", height: size, maxWidth: size * 1.7, objectFit: "contain", display: "block", flexShrink: 0 }} />
  );
  const Svg = m.svg;
  return <span title={m.name} style={{ display: "inline-flex", flexShrink: 0 }}><Svg s={size} /></span>;
};

export const BankBadge = ({ pay, size = 18, fallback }) => {
  ensureStyles();
  const k = bankKey(pay); const m = k && BANK_META[k];
  if (!m) return fallback || <span>{pay || "SHOP"}</span>;
  return (
    <span className="bk-pill" title={m.name} style={{
      display: "inline-flex", alignItems: "center", gap: 6, padding: "3px 10px 3px 7px", borderRadius: 999,
      background: m.bg, border: "1px solid " + m.border, color: m.color, fontWeight: 800, fontSize: 11.5, whiteSpace: "nowrap", lineHeight: 1,
    }}>
      <BankIcon pay={k} size={size} />
      <span className="bk-name">{m.short}</span>
    </span>
  );
};

/* tap-a-logo selector used inside the New Sale / Edit Sale forms */
export const BankPicker = ({ value, options, onChange, innerRef }) => {
  ensureStyles();
  const cur = bankKey(value);
  return (
    <div ref={innerRef} tabIndex={-1} role="radiogroup"
      style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(98px,1fr))", gap: 8, outline: "none" }}>
      {options.map(o => {
        const k = bankKey(o); const m = k && BANK_META[k];
        const on = cur === k;
        return (
          <button key={o} type="button" role="radio" aria-checked={on} className="bk-tile" onClick={() => onChange(o)}
            style={{
              display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", borderRadius: 10, cursor: "pointer", fontFamily: "inherit",
              border: "2px solid " + (on ? (m ? m.color : "#0f172a") : "#e2e8f0"),
              background: on ? (m ? m.bg : "#f1f5f9") : "white",
              color: on ? (m ? m.color : "#0f172a") : "#475569", fontWeight: on ? 800 : 600, fontSize: 12, textAlign: "left",
              boxShadow: on ? "0 2px 8px rgba(0,0,0,0.10)" : "none", transition: "all .12s",
            }}>
            {m ? <BankIcon pay={k} size={22} /> : null}
            <span className="bk-name" style={{ whiteSpace: "nowrap" }}>{m ? m.short : o}</span>
            {on && <span style={{ marginLeft: "auto", fontSize: 12 }}>✓</span>}
          </button>
        );
      })}
    </div>
  );
};

/* small popup used by the Payment column in the Sales list */
export const BankMenu = ({ value, options, onPick, onClose }) => {
  ensureStyles();
  const cur = bankKey(value);
  useEffect(() => {
    const h = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, [onClose]);
  return (
    <div style={{ position: "relative", display: "inline-block" }}>
      <div onClick={onClose} style={{ position: "fixed", inset: 0, zIndex: 60, background: "transparent" }} />
      <div style={{
        position: "absolute", right: 0, top: "100%", marginTop: 4, zIndex: 61, background: "white", borderRadius: 12,
        border: "1px solid #e2e8f0", boxShadow: "0 12px 32px rgba(15,23,42,0.18)", padding: 6, minWidth: 160, textAlign: "left",
      }}>
        {options.map(o => {
          const k = bankKey(o); const m = k && BANK_META[k]; const on = cur === k;
          return (
            <button key={o} type="button" onClick={() => onPick(o)}
              style={{
                display: "flex", alignItems: "center", gap: 9, width: "100%", padding: "7px 10px", border: "none", borderRadius: 8, cursor: "pointer",
                background: on ? (m ? m.bg : "#f1f5f9") : "transparent", color: m ? m.color : "#334155",
                fontWeight: on ? 800 : 600, fontSize: 12.5, fontFamily: "inherit", textAlign: "left",
              }}
              onMouseEnter={e => { if (!on) e.currentTarget.style.background = "#f8fafc"; }}
              onMouseLeave={e => { if (!on) e.currentTarget.style.background = "transparent"; }}>
              <span style={{ width: 28, display: "inline-flex", justifyContent: "center" }}>{m ? <BankIcon pay={k} size={20} /> : null}</span>
              <span style={{ whiteSpace: "nowrap" }}>{m ? m.name : o}</span>
              {on && <span style={{ marginLeft: "auto" }}>✓</span>}
            </button>
          );
        })}
      </div>
    </div>
  );
};
